// Temporary observer fragment. Install only after the root releases the source
// barrier. This is a Rust fixture receipt, not a native replay golden.
pub(super) fn stage264_replay_probe(
    sim: &Simulation,
    label: &str,
    frame: i32,
    rng_before: serde_json::Value,
    draws: Vec<serde_json::Value>,
    due: serde_json::Value,
    result: serde_json::Value,
    rules_hash: u64,
) {
    use std::io::Write;
    let Ok(prefix) = std::env::var("VERA20K_REPLAY_PROBE") else {
        return;
    };
    let ids = sim.substrate.entities.keys_sorted();
    let actors: Vec<_> = ids
        .iter()
        .map(|&id| serde_json::to_value(sim.substrate.entities.get(id).unwrap()).unwrap())
        .collect();
    let actor_identities: Vec<_> = ids
        .iter()
        .map(|&id| {
            let actor = sim.substrate.entities.get(id).unwrap();
            serde_json::json!({
                "id": id,
                "type": sim.interner.resolve(actor.type_ref()),
                "owner": sim.interner.resolve(actor.owner()),
                "category": actor.category,
            })
        })
        .collect();
    let value = serde_json::json!({
        "observer_schema": 2,
        "evidence_level": "Observed Rust fixture execution; not gamemd output",
        "frame": frame,
        "binary_frame": sim.session.binary_frame,
        "tick": sim.session.tick,
        "state_hash": format!("{:016X}", sim.state_hash()),
        "rules_hash": format!("{rules_hash:016X}"),
        "game_options": &sim.session.game_options,
        "session": &sim.session,
        "actors": actors,
        "actor_identities": actor_identities,
        "rng_before": rng_before,
        "rng": { "scenario": &sim.scenario_rng, "main": &sim.main_rng, "mapgen": &sim.mapgen_rng },
        "rng_hex": { "scenario": sim.scenario_rng.native_state_hex(), "main": sim.main_rng.native_state_hex(), "mapgen": sim.mapgen_rng.native_state_hex() },
        "rng_fingerprints": [format!("{:016X}", sim.scenario_rng.state()), format!("{:016X}", sim.main_rng.state()), format!("{:016X}", sim.mapgen_rng.state())],
        "draws": draws,
        "due_commands": due,
        "frame_result": result,
        "logic": sim.live_object_order_snapshot(),
        "display": &sim.substrate.display,
        "pending_delete": &sim.substrate.pending_delete,
        "pending_commands": &sim.pending_commands,
        "next_stable_object_id": sim.substrate.next_stable_object_id,
        "native_unique_ids": &sim.native_unique_ids,
        "anims": &sim.substrate.anims,
        "voxel_anims": &sim.substrate.voxel_anims,
        "particle_systems": &sim.substrate.particle_systems,
        "projectiles": &sim.projectiles,
        "waves": &sim.waves,
        "active_wave_links": &sim.active_wave_links,
        "houses": &sim.houses,
        "production": &sim.production,
        "pending_debug": {
            "lifecycle_requests": format!("{:?}", sim.pending_lifecycle_requests),
            "rocket_detonations": format!("{:?}", sim.pending_rocket_detonations),
            "missile_detonations": format!("{:?}", sim.pending_missile_detonations),
            "projectile_detonations": format!("{:?}", sim.pending_projectile_detonations),
            "wave_damage_requests": format!("{:?}", sim.pending_wave_damage_requests),
            "fire_requests": format!("{:?}", sim.fire_requests),
            "smudge_requests": format!("{:?}", sim.pending_smudge_requests),
        },
    });
    let mut output = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(format!("{prefix}-{label}.jsonl"))
        .unwrap();
    writeln!(output, "{value}").unwrap();
}

