"""Diagnose full Rust replay receipts without changing pins or expectations.

This emits differences, not a parity verdict. It deliberately does not discard
new Stage/private fields, reconcile native values, or model engine decisions.
"""
import argparse
from collections import Counter
import hashlib
import json
from pathlib import Path
import re

EXPECTED_ROWS = {
    "global_parity_harness_tests.rs": 601,
    "bridge_parity_harness_tests.rs": 201,
    "slice6_retask_tests.rs": 17,
}
STREAMS = ("scenario", "main", "mapgen")
MISSING = object()

def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def load(path, count):
    rows = [json.loads(line) for line in path.read_text().splitlines() if line.strip()]
    assert len(rows) == count, (str(path), len(rows), count)
    assert [row["frame"] for row in rows] == list(range(-1, count - 1))
    assert all(row["observer_schema"] == 2 for row in rows)
    return rows

def diffs(left, right, path=""):
    if left is MISSING or right is MISSING:
        # Missing is not an observed JSON object: keep additions/removals at
        # their real path, including the complete original/new field value.
        yield {"path": path, "before": {"observer_missing": True} if left is MISSING else left,
               "after": {"observer_missing": True} if right is MISSING else right}
    elif isinstance(left, dict) and isinstance(right, dict):
        for key in sorted(left.keys() | right.keys()):
            yield from diffs(left.get(key, MISSING), right.get(key, MISSING), path+"/"+key)
    elif isinstance(left, list) and isinstance(right, list):
        for i in range(max(len(left), len(right))):
            yield from diffs(left[i] if i < len(left) else MISSING,
                right[i] if i < len(right) else MISSING, path+"/"+str(i))
    elif left != right:
        yield {"path": path, "before": left, "after": right}

def actor_map(row):
    actors = {str(actor["stable_id"]): actor for actor in row["actors"]}
    assert len(actors) == len(row["actors"])
    return actors

def raw_draws(row):
    return [{"before_indices": d["before_indices"], "value": d["value"]} for d in row["draws"]]

def caller_functions(draw):
    # Backtrace owner symbols can be unqualified (e.g. infantry_idle_action).
    # Associate each symbol with its following sim source path instead of
    # selecting generic thread-local symbols that happen to mention the crate.
    # Line/column and checkout root identify build layout, not RNG ownership.
    # Every original stack is retained in frame_differences / input JSONL.
    frames = re.findall(r"^\s*\d+:\s+([^\n]+)(?:\n\s+at ([^\n]+))?", draw.get("callers", ""), flags=re.M)
    result = []
    for function, location in frames:
        source = re.search(r"(?:^|/)(src/sim/[^:]+)(?::\d+:\d+)?$", location)
        if source:
            result.append({"function": function, "source": source[1]})
    return result

def first_change(before, after, project):
    for l, r in zip(before, after):
        lp, rp = project(l), project(r)
        if lp != rp:
            return {"frame": l["frame"], "differences": list(diffs(lp, rp))}
    return None

def compare(label, before_path, after_path):
    count = EXPECTED_ROWS[label]
    before, after = load(before_path, count), load(after_path, count)
    row_changes = Counter()
    first_by_path = {}
    for l, r in zip(before, after):
        for change in diffs(actor_map(l), actor_map(r)):
            path = change["path"]
            row_changes[path] += 1
            first_by_path.setdefault(path, {"frame": l["frame"], **change})
    # Keep every observed-field difference at every frame. The first-change
    # indexes below help navigation; they never substitute for this full data.
    # Input SHA pins retain both complete raw receipts including unmodified
    # caller stacks, so normalization cannot hide a state/draw discrepancy.
    frame_differences = []
    all_paths = Counter()
    all_first_by_path = {}
    for l, r in zip(before, after):
        changes = list(diffs(l, r))
        if changes:
            frame_differences.append({"frame": l["frame"], "differences": changes})
        for change in changes:
            path = change["path"]
            all_paths[path] += 1
            all_first_by_path.setdefault(path, {"frame": l["frame"], **change})
    results = {
        "rows": count,
        "changed_frame_count": len(frame_differences),
        "field_difference_count": sum(len(row["differences"]) for row in frame_differences),
        "frame_differences": frame_differences,
        "all_paths": [{"path": p, "changed_frames": n, "first": all_first_by_path[p]} for p, n in sorted(all_paths.items())],
        "before_sha256": sha(before_path),
        "after_sha256": sha(after_path),
        "all_field_differences_retained": True,
        "first_hash_change": first_change(before, after, lambda r: r["state_hash"]),
        "first_actor_change": first_change(before, after, actor_map),
        "actor_paths": [{"path": p, "changed_frames": n, "first": first_by_path[p]} for p, n in sorted(row_changes.items())],
        "first_raw_draw_change": first_change(before, after, raw_draws),
        "first_caller_change": first_change(before, after, lambda r: [caller_functions(d) for d in r["draws"]]),
        "first_commands_change": first_change(before, after, lambda r: r["due_commands"]),
        "first_input_context_change": first_change(before, after, lambda r: [r["rules_hash"], r["game_options"]]),
        "seed_actor_identities_equal": before[0]["actor_identities"] == after[0]["actor_identities"],
        "first_actor_identity_change": first_change(before, after, lambda r: r["actor_identities"]),
        "first_logic_change": first_change(before, after, lambda r: r["logic"]),
        "first_display_change": first_change(before, after, lambda r: r["display"]),
        "first_pending_change": first_change(before, after, lambda r: [r["pending_delete"], r["pending_commands"], r["pending_debug"]]),
        "first_dynamic_objects_change": first_change(before, after, lambda r: {k: r[k] for k in ["anims", "voxel_anims", "particle_systems", "projectiles", "waves", "active_wave_links"]}),
        "first_commit_or_command_count_change": first_change(before, after, lambda r: {
            "tick": r["tick"], "binary_frame": r["binary_frame"],
            "frame_committed": r["frame_result"].get("frame_committed") if r["frame_result"] else None,
            "executed_commands": r["frame_result"].get("executed_commands") if r["frame_result"] else None,
        }),
        "stream_receipts": {},
        "limits": [
            "These are Rust fixture observations, not gamemd replay goldens.",
            "Raw draws record indices/value/stacks, not a stream label; do not guess interleaving if multiple streams changed.",
            "New/removed private fields are listed without deciding whether they are equivalent or legitimate.",
            "Actor identity comparison includes terminal removals; seeding premise is compared separately at frame -1.",
            "Late-frame captures may miss intermediate queue states; a first-divergence object/owner observer must establish same-frame ordering.",
        ],
    }
    for stream in STREAMS:
        results["stream_receipts"][stream] = {
            "full_after_state_equal_every_frame": all(l["rng"][stream] == r["rng"][stream] for l, r in zip(before, after)),
            "full_before_state_equal_every_frame": all(l["rng_before"][stream] == r["rng_before"][stream] for l, r in zip(before, after)),
            "hex_equal_every_frame": all(l["rng_hex"][stream] == r["rng_hex"][stream] for l, r in zip(before, after)),
            "first_state_change": first_change(before, after, lambda r: r["rng"][stream]),
            "before_constant_from_seed": all(r["rng"][stream] == before[0]["rng"][stream] for r in before),
            "after_constant_from_seed": all(r["rng"][stream] == after[0]["rng"][stream] for r in after),
            "before_final_fingerprint": before[-1]["rng_fingerprints"][STREAMS.index(stream)],
            "after_final_fingerprint": after[-1]["rng_fingerprints"][STREAMS.index(stream)],
        }
    if results["first_raw_draw_change"] is not None:
        frame = results["first_raw_draw_change"]["frame"]
        l = before[frame+1]
        r = after[frame+1]
        index = next((i for i, pair in enumerate(zip(raw_draws(l), raw_draws(r))) if pair[0] != pair[1]), min(len(l["draws"]), len(r["draws"])))
        results["first_raw_draw_window"] = {
            "frame": frame, "draw_index": index,
            "before": l["draws"][max(0,index-2):index+3],
            "after": r["draws"][max(0,index-2):index+3],
        }
    return results


def recorded_delta(left, right, path=()):
    """Lossless observed-data codec only; no simulation/RNG calculation."""
    if isinstance(left, dict) and isinstance(right, dict):
        for key in sorted(left.keys() - right.keys()):
            yield {"path": list(path+(key,)), "delete": True}
        for key in sorted(right):
            if key not in left:
                yield {"path": list(path+(key,)), "value": right[key]}
            else:
                yield from recorded_delta(left[key], right[key], path+(key,))
    elif isinstance(left, list) and isinstance(right, list) and len(left) == len(right):
        for index, (l, r) in enumerate(zip(left, right)):
            yield from recorded_delta(l, r, path+(index,))
    elif left != right:
        yield {"path": list(path), "value": right}


def decode_recorded_delta(packet):
    import copy
    rows = [copy.deepcopy(packet["first_row"])]
    for step in packet["steps"]:
        row = copy.deepcopy(rows[-1])
        for change in step["changes"]:
            path = change["path"]
            owner = row
            for key in path[:-1]:
                owner = owner[key]
            if change.get("delete"):
                del owner[path[-1]]
            else:
                owner[path[-1]] = copy.deepcopy(change["value"])
        assert row["frame"] == step["frame"]
        rows.append(row)
    return rows


def encode_recorded_delta(rows, original_path):
    import copy
    packet = {
        "codec": "observed_json_field_delta_v1",
        "meaning": "First full observed row plus exact recorded replacements/deletions; arrays of changed length are replaced whole; no simulation or RNG model.",
        "rows": len(rows),
        "original_jsonl_sha256": sha(original_path),
        "canonical_rows_sha256": hashlib.sha256(json.dumps(rows, sort_keys=True, separators=(",", ":")).encode()).hexdigest(),
        "first_row": copy.deepcopy(rows[0]),
        "steps": [{"frame": r["frame"], "changes": list(recorded_delta(l, r))} for l, r in zip(rows, rows[1:])],
    }
    reconstructed = decode_recorded_delta(packet)
    assert reconstructed == rows, "lossless receipt roundtrip"
    assert packet["canonical_rows_sha256"] == hashlib.sha256(json.dumps(reconstructed, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    return packet


def main():
    p = argparse.ArgumentParser(__doc__)
    p.add_argument("--before-prefix", required=True)
    p.add_argument("--after-prefix", required=True)
    p.add_argument("--output", required=True, type=Path)
    args = p.parse_args()
    out = args.output.resolve()
    assert str(out).startswith(("/private/tmp/", "/tmp/")), "scratch output only"
    assert not out.exists(), "preserve previous diagnostic"
    report = {label: compare(label, Path(args.before_prefix+"-"+label+".jsonl"), Path(args.after_prefix+"-"+label+".jsonl")) for label in EXPECTED_ROWS}
    out.write_text(json.dumps(report, indent=2)+"\n")
    print(json.dumps({"report": str(out), "sha256": sha(out), "summaries": {
        label: {
            "rows": item["rows"], "changed_frames": item["changed_frame_count"],
            "field_differences": item["field_difference_count"],
            "first_change_frames": {key: value["frame"] if value is not None else None
                for key, value in item.items() if key.startswith("first_")},
            "full_stream_equality": {stream: item["stream_receipts"][stream]["full_after_state_equal_every_frame"] for stream in STREAMS},
        } for label, item in report.items()},
    }, indent=2))

if __name__ == "__main__":
    main()
